windows_10_storage.read_only_probe_powershell:
$ErrorActionPreference = 'Stop'
$drive = Get-CimInstance -ClassName Win32_LogicalDisk -Filter "DeviceID='C:'"
$os = Get-CimInstance -ClassName Win32_OperatingSystem
$partitions = @()
$partition_error = $null
try {
    $system = Get-Partition -DriveLetter C
    $partitions = @(Get-Partition -DiskNumber $system.DiskNumber | Sort-Object Offset | Select-Object DiskNumber,PartitionNumber,DriveLetter,Offset,Size,Type)
} catch { $partition_error = $_.Exception.Message }
[ordered]@{ captured_utc = [DateTime]::UtcNow.ToString('o'); guest = $os.Caption; build = $os.BuildNumber; drive = $drive.DeviceID; filesystem = $drive.FileSystem; total_bytes = $drive.Size; free_bytes = $drive.FreeSpace; partitions = $partitions; partition_query_error = $partition_error } | ConvertTo-Json -Depth 4 | Set-Content -Encoding ascii -LiteralPath '\\vboxsvr\VM\void-s7-audit.Wbw08GjA\guest-storage.json'
